//! Python-vs-Rust parity sweep: for 5 seeds x 3 arms, the Rust batch must
//! reproduce the Python batch EXACTLY — per-account correct flags, totals,
//! violations, invalid attempts, retries. 0 mismatches required.
//! Reference file: tests/parity_reference.txt, one line per (seed, arm):
//!   seed|arm|good|violations|invalid_attempts|retries|200-bit flags
//! Generated by the Python module; parsed here with std only.

use fsmcontrol::*;

fn load_reference() -> Vec<String> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/parity_reference.txt");
    let text = std::fs::read_to_string(path).expect("parity_reference.txt missing");
    text.lines().map(|l| l.to_string()).filter(|l| !l.is_empty()).collect()
}

#[test]
fn parity_sweep_zero_mismatches() {
    let rows = load_reference();
    assert_eq!(rows.len(), 15, "expected 5 seeds x 3 arms");
    let mut mismatches = 0usize;
    for row in &rows {
        let parts: Vec<&str> = row.split('|').collect();
        assert_eq!(parts.len(), 7, "bad row: {}", row);
        let seed: u64 = parts[0].parse().unwrap();
        let arm = parts[1];
        let want_good: usize = parts[2].parse().unwrap();
        let want_viol: u64 = parts[3].parse().unwrap();
        let want_invalid: u64 = parts[4].parse().unwrap();
        let want_retries: u64 = parts[5].parse().unwrap();
        let want_bits = parts[6];

        let accounts = make_accounts(200, seed);
        let (outcomes, summary) =
            run_batch(&accounts, arm, seed, 0.05, 0.35, 1000.0, 3, 20);
        let got_bits: String = outcomes
            .iter()
            .map(|o| if o.correct_and_by_procedure { '1' } else { '0' })
            .collect();
        let mut row_bad = false;
        if summary.correct_and_by_procedure != want_good {
            row_bad = true;
            eprintln!("seed {} {}: good {} != {}", seed, arm, summary.correct_and_by_procedure, want_good);
        }
        if summary.total_violations != want_viol {
            row_bad = true;
            eprintln!("seed {} {}: violations {} != {}", seed, arm, summary.total_violations, want_viol);
        }
        if summary.total_invalid_attempts != want_invalid {
            row_bad = true;
            eprintln!("seed {} {}: invalid {} != {}", seed, arm, summary.total_invalid_attempts, want_invalid);
        }
        if summary.total_retries != want_retries {
            row_bad = true;
            eprintln!("seed {} {}: retries {} != {}", seed, arm, summary.total_retries, want_retries);
        }
        if got_bits != want_bits {
            row_bad = true;
            let diffs = got_bits
                .chars()
                .zip(want_bits.chars())
                .filter(|(a, b)| a != b)
                .count();
            eprintln!("seed {} {}: per-account flags differ in {} positions", seed, arm, diffs);
        }
        if row_bad {
            mismatches += 1;
        }
    }
    assert_eq!(mismatches, 0, "{} of 15 parity rows mismatched", mismatches);
}
